html, body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: transparent;
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif;
}
.stage {
  position: fixed;
  inset: 0;
  display: grid;
  place-items: center;
  color: #fff;
  opacity: 1;
  animation: stage 2.3s ease both;
}
.wash, .rays, .particles { position: absolute; inset: 0; overflow: hidden; }
.wash { background: rgba(8, 8, 14, .72); }
.stage.rainbow .wash {
  background: linear-gradient(112deg, rgba(255,44,105,.86), rgba(255,201,61,.78), rgba(62,220,145,.78), rgba(47,157,255,.82), rgba(145,73,255,.86));
  background-size: 240% 100%;
  animation: rainbow 1.4s ease-in-out both;
}
.stage.neon .wash { background: rgba(8, 7, 24, .9); }
.stage.gold .wash { background: radial-gradient(circle at center, rgba(128,77,0,.88), rgba(9,7,4,.94) 68%); }
.stage.laser .wash { background: rgba(3, 13, 18, .9); }
.rays { opacity: .72; }
.stage.gold .rays {
  background: repeating-conic-gradient(from 0deg at 50% 50%, rgba(255,214,91,.26) 0 5deg, transparent 5deg 16deg);
  animation: rays 7s linear infinite;
}
.stage.neon .rays::before, .stage.neon .rays::after,
.stage.laser .rays::before, .stage.laser .rays::after {
  content: "";
  position: absolute;
  left: -10%;
  width: 120%;
  height: 3px;
  background: #41f3ff;
  box-shadow: 0 0 18px #41f3ff, 0 0 44px rgba(65,243,255,.75);
  transform: rotate(-12deg);
  animation: scan 1.1s ease-in-out both;
}
.stage.neon .rays::after, .stage.laser .rays::after {
  background: #ff4fa3;
  box-shadow: 0 0 18px #ff4fa3, 0 0 44px rgba(255,79,163,.75);
  transform: rotate(14deg);
  animation-delay: .16s;
}
.copy {
  position: relative;
  z-index: 2;
  width: min(82%, 980px);
  text-align: center;
  padding: 34px 44px 38px;
  border-top: 1px solid rgba(255,255,255,.4);
  border-bottom: 1px solid rgba(255,255,255,.28);
  text-shadow: 0 3px 22px rgba(0,0,0,.48);
  animation: copy 2.3s cubic-bezier(.2,.8,.2,1) both;
}
.kicker { font-size: 14px; font-weight: 700; letter-spacing: 0; opacity: .75; }
.message {
  margin: 20px auto 18px;
  font-size: 54px;
  line-height: 1.2;
  font-weight: 850;
  letter-spacing: 0;
  text-wrap: balance;
}
.seal { font-size: 16px; font-weight: 650; letter-spacing: 0; opacity: .82; }
.particle {
  position: absolute;
  left: 50%;
  top: 50%;
  width: var(--size);
  height: var(--size);
  border-radius: 2px;
  background: var(--color);
  box-shadow: 0 0 12px var(--color);
  animation: particle 1.35s cubic-bezier(.12,.66,.24,1) var(--delay) both;
}
@keyframes stage {
  0%, 78% { opacity: 1; }
  100% { opacity: 0; }
}
@keyframes rainbow {
  0% { background-position: 0 0; filter: saturate(.8) brightness(.7); }
  45% { background-position: 100% 0; filter: saturate(1.25) brightness(1.12); }
  100% { background-position: 10% 0; filter: saturate(.9) brightness(.72); }
}
@keyframes copy {
  0% { transform: scale(.92); opacity: 1; }
  18% { transform: scale(1.04); opacity: 1; }
  32%, 78% { transform: scale(1); opacity: 1; }
  100% { transform: scale(1.08); opacity: 0; }
}
@keyframes particle {
  0% { transform: translate(-50%, -50%) scale(.2) rotate(0deg); opacity: 0; }
  15% { opacity: 1; }
  100% { transform: translate(calc(-50% + var(--x)), calc(-50% + var(--y))) scale(1) rotate(var(--rot)); opacity: 0; }
}
@keyframes rays { to { transform: rotate(360deg); } }
@keyframes scan {
  0% { top: -20%; opacity: 0; }
  18% { opacity: 1; }
  82% { opacity: 1; }
  100% { top: 120%; opacity: 0; }
}

