const config = window.__notchEffect || {};
const params = config.params || {};
const allowed = ['rainbow', 'neon', 'gold', 'laser'];
const variant = allowed.includes(params.variant) ? params.variant : 'rainbow';
const stage = document.getElementById('stage');
const message = document.getElementById('message');
const particles = document.getElementById('particles');
stage.classList.add(variant);
message.textContent = String(params.message || '老铁牛逼666').slice(0, 72);
if (message.textContent.length > 34) message.style.fontSize = '38px';
else if (message.textContent.length > 24) message.style.fontSize = '44px';

const colors = variant === 'gold'
  ? ['#fff3b0', '#ffd05a', '#ff9f1c', '#ffffff']
  : ['#ff4f8b', '#ffd166', '#54e6a5', '#4cc9f0', '#a78bfa', '#ffffff'];
const count = config.intensity === 'reduced' ? 18 : 42;
for (let i = 0; i < count; i += 1) {
  const bit = document.createElement('i');
  bit.className = 'particle';
  const angle = Math.random() * Math.PI * 2;
  const distance = 130 + Math.random() * 420;
  bit.style.setProperty('--x', Math.cos(angle) * distance + 'px');
  bit.style.setProperty('--y', Math.sin(angle) * distance + 'px');
  bit.style.setProperty('--rot', (Math.random() * 720 - 360) + 'deg');
  bit.style.setProperty('--size', (3 + Math.random() * 8) + 'px');
  bit.style.setProperty('--delay', (Math.random() * .32) + 's');
  bit.style.setProperty('--color', colors[i % colors.length]);
  particles.appendChild(bit);
}
setTimeout(() => notchany.finish(), 2200);

