import json
import os
import random
import re
import urllib.error
import urllib.request


PRAISES = {
    "热血": [
        "{name}一出手，含金量直接拉满！",
        "别人是发挥稳定，{name}是稳定超神！",
        "{name}这波操作，教科书看了都得改版！",
        "全场请注意，{name}又开始不讲道理地优秀了！",
        "{name}今天这个状态，冠军见了都得递水！",
        "这不是高光时刻，这是{name}的日常水平！",
        "{name}负责出手，剩下的人负责喊666！",
    ],
    "温柔": [
        "{name}认真生活的样子，本身就很闪亮。",
        "今天也要记得，{name}已经做得很好了。",
        "{name}身上那股靠谱劲儿，让人特别安心。",
        "世界有点吵，但{name}的光一直很稳。",
        "{name}不用刻意证明，优秀早就藏不住了。",
        "遇见{name}这种宝藏，是今天的小幸运。",
    ],
    "离谱": [
        "建议给{name}单独开个段位，普通王者装不下！",
        "{name}这实力，导航看了都说您已超出地图范围！",
        "科学家连夜研究：{name}到底怎么能这么顶？",
        "{name}一认真，困难自己就开始写检讨了！",
        "听说天花板很高，{name}抬手就给掀了！",
        "{name}不是来参与的，是来刷新纪录的！",
    ],
    "江湖": [
        "江湖路远，{name}一出场就是定海神针！",
        "这一局有{name}坐镇，稳得像祖传招牌！",
        "各路豪杰先别争，{name}的排面已经到位！",
        "{name}这身本事，放哪儿都是镇场子的存在！",
        "今日江湖头条：{name}又帅气地解决了一切！",
        "有{name}在，难题见面都得先抱拳！",
    ],
    "职场": [
        "{name}这执行力，待办列表看了都自动清空！",
        "关键时刻还得看{name}，稳准狠全占了！",
        "{name}交付的不是结果，是行业标杆！",
        "会议可以少开，但{name}的掌声不能少！",
        "{name}这思路一打开，问题就只剩下配合！",
        "靠谱这两个字，今天建议直接改名叫{name}！",
    ],
}

BADGES = ["牛逼", "封神", "太顶", "666", "无敌", "天秀", "稳了", "靠谱"]
RANDOM_EFFECTS = [
    "fireworks", "fireworks", "confetti", "confetti",
    "rainbow", "rainbow", "neon", "gold", "laser",
]
DEFAULT_AI_PROMPT = (
    "给一个叫“{name}”的人写一句中文彩虹屁，风格是“{style}”。"
    "要求积极、好玩、有画面感，像朋友当面夸人；一句话，最好不超过32个汉字；"
    "不要解释，不要加引号，不要涉及攻击、色情、政治或歧视。"
)


def param(key, default=""):
    return os.environ.get("NOTCH_PARAM_" + key.upper(), default)


def payload():
    raw = os.environ.get("NOTCH_WIDGET_PAYLOAD", "").strip()
    if not raw:
        return {}
    try:
        value = json.loads(raw)
        return value if isinstance(value, dict) else {}
    except Exception:
        return {}


def clean_name(value):
    value = re.sub(r"\s+", " ", (value or "").strip())
    return value[:16] or "老铁"


def clean_praise(value):
    value = re.sub(r"\s+", " ", (value or "").strip())
    value = value.strip("\"'“”‘’ ")
    if not value:
        return ""
    return value[:72]


def built_in_praise(name, style):
    choices = PRAISES.get(style) or PRAISES["热血"]
    return random.choice(choices).format(name=name)


def api_request(messages, max_tokens=100, temperature=1.15):
    key = param("api_key", "").strip()
    endpoint = param("ai_endpoint", "https://api.openai.com/v1/chat/completions").strip()
    model = param("ai_model", "gpt-4.1-mini").strip()
    if not key:
        return "", "请先在参数里填写 AI API Key"
    if not endpoint:
        return "", "AI 接口地址不能为空"
    if not model:
        return "", "AI 模型不能为空"

    body = {
        "model": model,
        "messages": messages,
        "temperature": temperature,
        "max_tokens": max_tokens,
    }
    request = urllib.request.Request(
        endpoint,
        data=json.dumps(body, ensure_ascii=False).encode("utf-8"),
        headers={
            "Authorization": "Bearer " + key,
            "Content-Type": "application/json",
        },
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=9) as response:
            data = json.load(response)
    except urllib.error.HTTPError as error:
        detail = ""
        try:
            raw = error.read().decode("utf-8", "replace")
            data = json.loads(raw)
            payload = data.get("error") if isinstance(data, dict) else None
            detail = payload.get("message", "") if isinstance(payload, dict) else ""
        except Exception:
            detail = ""
        detail = re.sub(r"\s+", " ", detail).strip()[:180]
        return "", f"HTTP {error.code}" + (f"：{detail}" if detail else "")
    except urllib.error.URLError as error:
        reason = re.sub(r"\s+", " ", str(error.reason)).strip()[:180]
        return "", "网络连接失败" + (f"：{reason}" if reason else "")
    except (OSError, ValueError, KeyError) as error:
        detail = re.sub(r"\s+", " ", str(error)).strip()[:180]
        return "", "请求失败" + (f"：{detail}" if detail else "")

    choices = data.get("choices") if isinstance(data, dict) else None
    if not isinstance(choices, list) or not choices:
        return "", "接口已响应，但返回格式不是兼容的 chat/completions"
    message = choices[0].get("message") if isinstance(choices[0], dict) else None
    content = message.get("content") if isinstance(message, dict) else ""
    content = clean_praise(content)
    if not content:
        return "", "接口已响应，但没有返回文本内容"
    return content, ""


def ai_praise(name, style):
    if param("use_ai", "0") != "1":
        return ""
    template = param("ai_prompt", DEFAULT_AI_PROMPT).strip() or DEFAULT_AI_PROMPT
    prompt = template.replace("{name}", name).replace("{style}", style)[:1200]
    content, _ = api_request(
        [
            {"role": "system", "content": "你是一个有分寸、脑洞大、绝不重复套话的夸夸搭子。"},
            {"role": "user", "content": prompt},
        ]
    )
    return content


def test_ai_connection():
    content, error = api_request(
        [
            {"role": "system", "content": "你正在进行 API 连通性测试。"},
            {"role": "user", "content": "只回复：连接成功"},
        ],
        max_tokens=20,
        temperature=0,
    )
    if error:
        state = {
            "badge": "失败",
            "phrase": error,
            "effect": "idle",
            "source": "test",
            "connection": "failed",
        }
        notch_result(summary="AI 连接失败", details=error, widget=state)
        return
    model = param("ai_model", "gpt-4.1-mini").strip()
    state = {
        "badge": "已连",
        "phrase": f"{model} 连接正常",
        "effect": "idle",
        "source": "test",
        "connection": "ok",
    }
    notch_result(summary="AI 连接成功", details=f"{model} · {content}", widget=state)


def choose_effect(phrase):
    selected = param("effect", "随机").strip() or "随机"
    mapping = {
        "烟花": "fireworks",
        "彩纸": "confetti",
        "彩虹": "rainbow",
        "霓虹": "neon",
        "金光": "gold",
        "激光": "laser",
    }
    effect = random.choice(RANDOM_EFFECTS) if selected == "随机" else mapping.get(selected, "rainbow")
    if effect in ("fireworks", "confetti"):
        return effect, {"preset": effect}
    return effect, {
        "custom": True,
        "duration_ms": 2300,
        "params": {"variant": effect, "message": phrase},
    }


def idle_state():
    return {
        "badge": "夸我",
        "phrase": "点击领取今日份彩虹屁",
        "effect": "idle",
        "source": "ready",
        "connection": "idle",
    }


def main():
    event = os.environ.get("NOTCH_WIDGET_EVENT", "").strip()
    if event in ("refresh", "trigger"):
        notch_result(widget=idle_state())
        return
    if event == "test_ai":
        test_ai_connection()
        return

    data = payload()
    name = clean_name(data.get("name") if isinstance(data.get("name"), str) else param("target_name", "老铁"))
    style = param("style", "热血").strip() or "热血"
    phrase = ai_praise(name, style)
    source = "AI" if phrase else "内置"
    if not phrase:
        phrase = built_in_praise(name, style)
    badge = random.choice(BADGES)
    effect_name, effect_request = choose_effect(phrase)
    state = {
        "badge": badge,
        "phrase": phrase,
        "effect": effect_name,
        "source": source,
    }
    notch_result(
        summary=phrase,
        details=f"{source}彩虹屁 · {style}模式 · 再点一次继续夸",
        widget=state,
        effect=effect_request,
    )


if __name__ == "__main__":
    main()

