const button = document.getElementById('praise');
const testButton = document.getElementById('test');
const testCompact = document.getElementById('testCompact');
const testWide = document.getElementById('testWide');
const badge = document.getElementById('badge');
const phrase = document.getElementById('phrase');
const hint = document.getElementById('hint');

function render(result) {
  if (!result || !result.ok || !result.state) return false;
  const state = result.state;
  badge.textContent = state.badge || '666';
  phrase.textContent = state.phrase || '点击领取今日份彩虹屁';
  hint.textContent = state.source === 'AI' ? 'AI 夸的' : state.source === '内置' ? '再来一句' : '点一下';
  button.title = state.phrase || '来句彩虹屁';
  button.setAttribute('aria-label', state.phrase || '来句彩虹屁');
  button.dataset.effect = state.effect || '';
  testButton.classList.toggle('ok', state.connection === 'ok');
  testButton.classList.toggle('bad', state.connection === 'failed');
  testCompact.textContent = state.connection === 'ok' ? '已连' : state.connection === 'failed' ? '重试' : '测试';
  testWide.textContent = state.connection === 'ok' ? '✓ 已连接' : state.connection === 'failed' ? '! 配置错误' : '测试 AI';
  testButton.title = state.connection === 'ok'
    ? 'AI 配置验证通过，点击可重新测试'
    : state.connection === 'failed'
      ? (state.phrase || 'AI 配置验证失败，点击重试')
      : '验证 AI 接口、模型与 API Key 配置';
  if (state.source === 'test') hint.textContent = state.connection === 'ok' ? 'AI 正常' : '检查配置';
  return true;
}

async function praise() {
  if (button.classList.contains('busy')) return;
  button.classList.add('busy');
  hint.textContent = '酝酿中';
  const result = await notchany.execute('praise', null);
  button.classList.remove('busy');
  if (!render(result)) hint.textContent = '再点一次';
}

async function refresh() {
  const result = await notchany.invoke('refresh', null);
  render(result);
}

async function testConnection() {
  if (testButton.classList.contains('busy')) return;
  testButton.classList.add('busy');
  testCompact.textContent = '测试中';
  testWide.textContent = '正在验证…';
  hint.textContent = '测试中';
  const result = await notchany.execute('test_ai', null);
  testButton.classList.remove('busy');
  if (!render(result)) {
    testCompact.textContent = '重试';
    testWide.textContent = '! 测试失败';
    testButton.classList.add('bad');
    hint.textContent = '测试失败';
  }
}

button.addEventListener('click', praise);
testButton.addEventListener('click', testConnection);
notchany.addEventListener('statechange', event => render(event.state));
notchany.addEventListener('visibilitychange', () => {
  if (notchany.visible && !notchany.state) refresh();
});
if (notchany.state) render(notchany.state);
if (notchany.visible && !notchany.state) refresh();
